// ══════════════ M15c 任务/签到/通行证/会员 ══════════════

// ListTasksQuery GET /tasks?period=&pageSize=&pageToken=（公开，可选登录绑定）
type ListTasksQuery struct {
	Period    int64  `form:"period,optional"` // 0=全部 1=once 2=daily 3=weekly
	PageSize  int64  `form:"pageSize,optional"`
	PageToken string `form:"pageToken,optional"`
}

// TaskResp 任务视图
type TaskResp struct {
	TaskId           int64  `json:"taskId"`
	Version          int64  `json:"version"`
	Name             string `json:"name"`
	Period           int64  `json:"period"`
	Metric           int64  `json:"metric"`
	Target           int64  `json:"target"`
	CycleLimit       int64  `json:"cycleLimit"` // 0=不限
	RewardTemplateId string `json:"rewardTemplateId"`
	RewardCount      int64  `json:"rewardCount"`
	Progress         int64  `json:"progress"` // SIGN_IN=streak，其他=amount
	Claimed          int64  `json:"claimed"`
	State            int64  `json:"state"` // 1 进行中 2 可领取 3 已完成
}

// ListTasksResp 任务分页 + 通行证/会员视图（本仓前端展示扩展）
type ListTasksResp struct {
	Tasks         []TaskResp  `json:"tasks"`
	NextPageToken string      `json:"nextPageToken,omitempty"`
	Passes        []PassResp  `json:"passes,omitempty"`
	Member        *MemberResp `json:"member,omitempty"`
}

// PassRewardResp 通行证奖励视图
type PassRewardResp struct {
	Level            int64  `json:"level"`
	Track            int64  `json:"track"` // 1 FREE 2 PREMIUM
	RewardTemplateId string `json:"rewardTemplateId"`
	RewardCount      int64  `json:"rewardCount"`
}

// PassResp 通行证赛季 + 用户进度视图
type PassResp struct {
	PassId             int64            `json:"passId"`
	Version            int64            `json:"version"`
	Name               string           `json:"name"`
	XpPerLevel         int64            `json:"xpPerLevel"`
	MaxLevel           int64            `json:"maxLevel"`
	Rewards            []PassRewardResp `json:"rewards"`
	XpPerSpendMinor    int64            `json:"xpPerSpendMinor"`
	PremiumLine        int64            `json:"premiumLine"` // 0 无 1 付费解锁 2 会员
	PremiumMemberLevel int64            `json:"premiumMemberLevel"`
	Xp                 int64            `json:"xp"`     // 用户当前 XP
	Level              int64            `json:"level"`  // 用户当前等级
	Premium            bool             `json:"premium"` // 高级线已解锁
}

// MemberTierResp 会员档位视图
type MemberTierResp struct {
	Level            int64  `json:"level"`
	SpendMinor       int64  `json:"spendMinor"`
	RewardTemplateId string `json:"rewardTemplateId"`
	RewardCount      int64  `json:"rewardCount"`
}

// MemberResp 会员档位 + 用户消费视图
type MemberResp struct {
	Tiers      []MemberTierResp `json:"tiers"`
	SpendMinor int64            `json:"spendMinor"`
	Level      int64            `json:"level"`
}

